#!/bin/sh
# Generate session bundles: usage/bundles/<role>-<skill>.md
#
# Each bundle is one skill's full session load — system conventions + the glossary
# template + the role file + the skill — concatenated in load order, so a session is a
# single paste (see docs/0.1.1-plans/02-first-run.md, item C6).
#
# GENERATED FILE: never edit the bundles by hand; regenerate with `make bundles` after
# any change to the canonical files. `make check-bundles` guards freshness.
#
# Usage: scripts/build-bundles.sh [output-dir]
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"
out="${1:-$root/usage/bundles}"

rm -rf "$out"
mkdir -p "$out"

conv="$root/shared/system-conventions.md"
gloss="$root/shared/glossary-and-org.md"

for skill_file in "$root"/skills/*/*/SKILL.md; do
  role_dir="$(dirname "$(dirname "$skill_file")")"
  role="$(basename "$role_dir")"
  skill="$(basename "$(dirname "$skill_file")")"
  role_file="$root/roles/$role.md"
  dest="$out/$role-$skill.md"

  {
    printf '<!-- GENERATED by `make bundles` from the canonical files — do not edit. Regenerate on upgrade. -->\n\n'
    printf '# Session bundle — %s / %s\n\n' "$role" "$skill"
    printf 'One paste for the whole session load. For real runs, paste **your** filled\n'
    printf '`my-org.md` right after this file (see docs/UPGRADING.md).\n\n'
    printf -- '---\n\n<!-- shared/system-conventions.md -->\n\n'
    cat "$conv"
    printf '\n\n---\n\n<!-- shared/glossary-and-org.md — TEMPLATE: replace with your own my-org.md for real runs -->\n\n'
    cat "$gloss"
    printf '\n\n---\n\n<!-- roles/%s.md -->\n\n' "$role"
    cat "$role_file"
    printf '\n\n---\n\n<!-- skills/%s/%s/SKILL.md -->\n\n' "$role" "$skill"
    cat "$skill_file"
  } > "$dest"
done

count="$(ls "$out" | wc -l | tr -d ' ')"
echo "wrote $count bundles to ${out#"$root"/}"
